// Generated by esquadro: do not edit. A many-to-many relation in the form:
// the records chosen as chips, and a search to add or take some off.
import { useQueries, useQuery, useQueryClient } from "@tanstack/react-query"
import { Check, Plus, X } from "../icons.gen.ts"
import { useEffect, useState } from "react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"
import { api } from "../api.ts"
import { resources } from "../resources.gen.ts"
import { capitalize, t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"

const targetOf = (field: FieldMeta) => (resources as unknown as Record<string, ResourceMeta>)[field.target ?? ""]

/** The links of a relation, as the API lists them: a page of its records. */
type Links = { list(id: string, query?: { limit?: number }, o?: { signal?: AbortSignal }): Promise<{ items: Rec[] }> }

/**
 * The records a record is linked to, for the form to start with: their ids,
 * by field (tag_ids), each record kept in the cache so its chip has a name.
 */
export function useLinked(meta: ResourceMeta, fields: FieldMeta[], id: string | undefined) {
  const queryClient = useQueryClient()
  const many = fields.filter((f) => f.kind === "many" && f.relation)
  const linked = useQueries({
    queries: many.map((f) => ({
      queryKey: [meta.name, "links", f.relation, id],
      queryFn: async ({ signal }: { signal: AbortSignal }) => {
        const links = (meta.api(api as never) as unknown as Record<string, Links>)[f.relation!]
        const page = await links.list(id!, { limit: 100 }, { signal })
        const target = targetOf(f)
        for (const r of page.items) if (target) queryClient.setQueryData([target.name, "get", r.id], r)
        return page.items.map((r) => r.id)
      },
      enabled: id !== undefined,
    })),
  })
  return {
    pending: id !== undefined && linked.some((l) => l.isPending),
    values: Object.fromEntries(many.map((f, i) => [f.name, linked[i]?.data ?? []])),
  }
}

/** A chosen record, by its name: from the cache, or read once. */
function Chip({ target, display, id, onRemove }: { target: ResourceMeta; display: string; id: string; onRemove: () => void }) {
  const record = useQuery({
    queryKey: [target.name, "get", id],
    queryFn: ({ signal }) => target.api(api as never).get(id, {}, { signal }),
    staleTime: 60_000,
  })
  return (
    <Badge variant="secondary" className="h-7 gap-1 pr-1 pl-2.5 text-sm">
      {record.isPending ? <Skeleton className="h-3 w-12" /> : capitalize(String(record.data?.[display] ?? id.slice(0, 8)))}
      <button
        type="button"
        className="rounded-sm p-0.5 text-muted-foreground hover:bg-background hover:text-foreground"
        aria-label={t("remove")}
        onClick={onRemove}
      >
        <X className="size-3.5" />
      </button>
    </Badge>
  )
}

/** The records of a many-to-many relation: chips, and a search to change them. */
export function ManyInput({
  id,
  field,
  value,
  onChange,
  invalid,
}: {
  id: string
  field: FieldMeta
  value: unknown
  onChange: (v: unknown) => void
  invalid?: boolean
}) {
  const target = targetOf(field)
  const chosen = Array.isArray(value) ? (value as string[]) : []
  const [open, setOpen] = useState(false)
  const [typed, setTyped] = useState("")
  const [q, setQ] = useState("")
  const [active, setActive] = useState("")
  // After a pause in typing, search.
  useEffect(() => {
    const timer = setTimeout(() => setQ(typed.trim()), 250)
    return () => clearTimeout(timer)
  }, [typed])
  const queryClient = useQueryClient()
  const searchable = target?.sorts.includes("relevance") ?? false
  const options = useQuery({
    queryKey: [target?.name, "options", searchable ? q : ""],
    queryFn: async ({ signal }) => {
      const page = await target.api(api as never).list({ ...(searchable && q ? { q } : {}), per_page: 20, limit: 20 }, { signal })
      for (const r of page.items) queryClient.setQueryData([target.name, "get", r.id], r)
      return page.items
    },
    enabled: open && target !== undefined,
  })
  const display = field.display ?? "id"
  const toggle = (rid: string) => onChange(chosen.includes(rid) ? chosen.filter((x) => x !== rid) : [...chosen, rid])
  // Without a search in the API, the list filters what it read.
  const items = (options.data ?? []).filter((r) => searchable || !q || String(r[display] ?? "").toLowerCase().includes(q.toLowerCase()))
  // A new search highlights its first record, for Enter.
  const shown = items.map((r) => r.id).join()
  useEffect(() => {
    const ids = shown ? shown.split(",") : []
    setActive((a) => (ids.includes(a) ? a : (ids[0] ?? "")))
  }, [shown])
  if (!target) return null
  return (
    <div
      id={id}
      aria-invalid={invalid}
      className={cn(
        "flex min-h-9 flex-wrap items-center gap-1.5 rounded-lg border border-input bg-transparent px-1.5 py-1 shadow-xs",
        invalid && "border-destructive",
      )}
    >
      {chosen.map((rid) => (
        <Chip key={rid} target={target} display={display} id={rid} onRemove={() => toggle(rid)} />
      ))}
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button type="button" variant="ghost" size="sm" className="h-7 text-muted-foreground">
            <Plus /> {chosen.length === 0 ? t("choose") : t("add")}
          </Button>
        </PopoverTrigger>
        <PopoverContent align="start" className="w-72 p-0">
          <Command shouldFilter={false} value={active} onValueChange={setActive}>
            <CommandInput value={typed} onValueChange={setTyped} placeholder={t("searchIn", { name: target.label.toLocaleLowerCase() })} />
            <CommandList>
              {options.isPending ? (
                <div className="flex flex-col gap-2 p-3">
                  <Skeleton className="h-6 w-full" />
                  <Skeleton className="h-6 w-2/3" />
                </div>
              ) : (
                <>
                  <CommandEmpty>{t("noResults")}</CommandEmpty>
                  <CommandGroup>
                    {items.map((r) => (
                      <CommandItem key={r.id} value={r.id} onSelect={() => toggle(r.id)}>
                        <Check className={cn("size-4", chosen.includes(r.id) ? "opacity-100" : "opacity-0")} />
                        {capitalize(String(r[display] ?? r.id))}
                      </CommandItem>
                    ))}
                  </CommandGroup>
                </>
              )}
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    </div>
  )
}
